<?php require '../database.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$action=$_POST['action']??'';$s=$conn->prepare("SELECT book_id,status FROM issues WHERE id=?");$s->bind_param("i",$id);$s->execute();$r=$s->get_result()->fetch_assoc();if($r&&$r['status']==='Pending'&&$action==='approve'){$conn->begin_transaction();$q=$conn->prepare("UPDATE books SET available=available-1 WHERE id=? AND available>0");$q->bind_param("i",$r['book_id']);$q->execute();if($q->affected_rows){$q=$conn->prepare("UPDATE issues SET status='Issued' WHERE id=?");$q->bind_param("i",$id);$q->execute();$conn->commit();}else $conn->rollback();}elseif($r&&$r['status']==='Pending'&&$action==='reject'){$q=$conn->prepare("UPDATE issues SET status='Rejected' WHERE id=?");$q->bind_param("i",$id);$q->execute();}header("Location: issues.php");exit;}$rows=$conn->query("SELECT i.*,u.name,u.email,b.title FROM issues i JOIN users u ON u.id=i.user_id JOIN books b ON b.id=i.book_id ORDER BY i.id DESC");?><!doctype html><html><head><title>Requests</title><link rel="stylesheet" href="../style.css"></head><body><header><b>Admin</b><nav><a href="dashboard.php">Dashboard</a><a href="books.php">Books</a><a href="students.php">Students</a><a href="../logout.php">Logout</a></nav></header><main class="container"><h1>Book Requests and Issues</h1><table><tr><th>Student</th><th>Book</th><th>Dates</th><th>Status</th><th>Action</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['name'])?><br><?=e($r['email'])?></td><td><?=e($r['title'])?></td><td><?=e($r['issue_date'])?><br>Due: <?=e($r['due_date'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='Pending'):?><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="approve">Approve</button> <button name="action" value="reject" class="secondary">Reject</button></form><?php elseif($r['status']==='Issued'):?><form method="post" action="return.php"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Mark Returned</button></form><?php endif;?></td></tr><?php endwhile;?></table></main></body></html>